<?php
/** @var array $d Published, filtered release events. */
namespace MSC;
?>
<div class="release-guide-content" data-filters="<?php echo esc_attr( wp_json_encode( $f ) ); ?>">
<header class="release-guide-heading"><div><p class="release-eyebrow">Release guide</p><<?php echo $heading_tag; ?>><?php echo $selected ? esc_html( $selected['title'] . ' releases' ) : 'Upcoming releases'; ?></<?php echo $heading_tag; ?>><p>Browse release dates by title, month<?php echo $directory ? ", and streaming service" : ""; ?>.</p></div><div class="release-guide-summary"><strong><?php echo esc_html( $d['total'] ); ?></strong><span>releases in <?php echo esc_html( wp_date( 'F', $month->getTimestamp() ) ); ?></span></div></header>
<nav class="release-months" aria-label="Release months">
<?php for ( $i = -1; $i <= 7; ++$i ) { $target = $month->modify( ( $i >= 0 ? '+' : '' ) . $i . ' months' ); if ( $target->format( 'Y' ) < '1900' || $target->format( 'Y' ) > '2200' ) { continue; } $nav = array_replace( $f, array( 'month' => $target->format( 'Y-m' ), 'page' => 1 ) ); ?><a data-release-nav href="<?php echo esc_url( self::url( $nav, $base ) ); ?>"<?php echo 0 === $i ? ' aria-current="date"' : ''; ?>><span><?php echo esc_html( wp_date( 'M', $target->getTimestamp() ) ); ?></span><small><?php echo esc_html( $target->format( 'Y' ) ); ?></small></a><?php } ?>
</nav>
<form class="release-guide-filters" action="<?php echo esc_url( $base ); ?>" method="get">
<input type="hidden" name="release_month" value="<?php echo esc_attr( $f['month'] ); ?>"><input type="hidden" name="release_service" value="<?php echo esc_attr( $f['service'] ); ?>">
<label class="release-search">Search titles<input name="release_search" type="search" placeholder="Title or TV show" value="<?php echo esc_attr( $f['search'] ); ?>"></label>
<label>Content type<select name="release_type"><option value="">All release types</option><?php foreach ( self::types() as $type => $fields ) { ?><option value="<?php echo esc_attr( $type ); ?>"<?php selected( $f['type'], $type ); ?>><?php echo esc_html( Schema::get( $type )['label'] ); ?></option><?php } ?></select></label>
<label>View<select name="release_view"><option value="cards"<?php selected( $f['view'], 'cards' ); ?>>Cards</option><option value="list"<?php selected( $f['view'], 'list' ); ?>>Compact list</option></select></label>
<label class="release-past"><input type="checkbox" name="release_past" value="1"<?php checked( $f['past'], '1' ); ?>> Include earlier dates</label><button type="submit">Apply filters</button>
</form>
<?php if ( $directory ) { ?>
<section class="release-services" aria-labelledby="release-services-label"><div class="release-section-title"><h2 id="release-services-label">Streaming services</h2><a href="<?php echo esc_url( get_post_type_archive_link( 'msc_streaming' ) ); ?>">Service profiles <span aria-hidden="true">↗</span></a></div>
<div class="release-service-picker"><a class="release-service-choice release-service-all" data-release-nav href="<?php echo esc_url( self::url( array_replace( $f, array( 'service' => '', 'page' => 1 ) ), $base ) ); ?>"<?php echo ! $selected ? ' aria-current="true"' : ''; ?>><strong>All services</strong><span>and other releases</span></a>
<?php foreach ( $directory as $service ) { ?><a class="release-service-choice" data-release-nav href="<?php echo esc_url( self::url( array_replace( $f, array( 'service' => $service['uuid'], 'page' => 1 ) ), $base ) ); ?>"<?php echo $f['service'] === $service['uuid'] ? ' aria-current="true"' : ''; ?>><?php echo self::service_logo( $service ); ?><strong><?php echo esc_html( $service['title'] ); ?></strong><span><?php echo esc_html( $d['counts'][ $service['uuid'] ] . ( 1 === $d['counts'][ $service['uuid'] ] ? ' release' : ' releases' ) ); ?></span></a><?php Attribution::collect_media( (array) $service['logo_ref'], $service['title'] ); } ?>
</div></section>
<?php } ?>
<?php if ( $selected ) { ?><aside class="release-selected-service"><?php echo self::service_logo( $selected ); ?><div><strong><?php echo esc_html( $selected['title'] ); ?></strong><p>Scheduled releases assigned to this service.</p></div><a href="<?php echo esc_url( $selected['url'] ); ?>">Service profile ↗</a><?php if ( $selected['website'] ) { ?><a href="<?php echo esc_url( $selected['website'] ); ?>" target="_blank" rel="noopener">Official website ↗</a><?php } ?></aside><?php } ?>
<div class="release-results-heading"><div><p class="release-eyebrow">Monthly schedule</p><h2><?php echo esc_html( wp_date( 'F Y', $month->getTimestamp() ) ); ?></h2></div><div><span class="release-result-count" role="status"><?php echo esc_html( $d['total'] . ( 1 === $d['total'] ? ' release' : ' releases' ) ); ?> · <?php echo esc_html( $d['days'] . ( 1 === $d['days'] ? ' date' : ' dates' ) ); ?></span><a href="<?php echo esc_url( add_query_arg( array( 'calendar_month' => $f['month'], 'release_service' => $f['service'], 'release_type' => $f['type'] ), NetworkSites::calendar_url() ) ); ?>">Calendar grid ↗</a></div></div>
<div class="release-result-days" data-view="<?php echo esc_attr( $f['view'] ); ?>">
<?php $groups = array(); foreach ( $d['events'] as $event ) { $groups[ $event['date'] ][] = $event; } foreach ( $groups as $day => $events ) { $date = new \DateTimeImmutable( $day . ' 12:00:00', wp_timezone() ); ?>
<section class="release-date-group" data-date="<?php echo esc_attr( $day ); ?>"><header class="release-date-heading"><time datetime="<?php echo esc_attr( $day ); ?>"><strong><?php echo esc_html( $date->format( 'd' ) ); ?></strong><span><?php echo esc_html( wp_date( 'l', $date->getTimestamp() ) ); ?><small><?php echo esc_html( wp_date( 'F Y', $date->getTimestamp() ) ); ?></small></span></time><span><?php echo count( $events ) . ( 1 === count( $events ) ? ' release' : ' releases' ); ?></span></header><div class="release-guide-cards<?php echo 1 === count( $events ) ? ' release-one' : ( 2 === count( $events ) ? ' release-two' : '' ); ?>">
<?php foreach ( $events as $event ) { $r = $event['record']; ?>
<article class="release-guide-card type-<?php echo esc_attr( $r['type'] ); ?>"><a class="release-guide-art" href="<?php echo esc_url( $event['url'] ); ?>" tabindex="-1" aria-hidden="true"><?php echo Presentation::image( $r, '', 'medium_large' ); ?></a><div class="release-guide-card-copy"><p class="release-card-kind"><?php echo esc_html( $event['label'] ); ?></p><?php if ( $event['show_title'] ) { ?><p class="release-card-parent"><?php if ( $event['parent_url'] ) { ?><a href="<?php echo esc_url( $event['parent_url'] ); ?>"><?php echo esc_html( $event['show_title'] ); ?></a><?php } else { echo esc_html( $event['show_title'] ); } ?></p><?php } ?><h3><a href="<?php echo esc_url( $event['url'] ); ?>"><?php echo esc_html( $event['title'] ); ?></a></h3>
<?php if ( $event['platforms'] || $event['region'] ) { ?><p class="release-card-platforms"><?php echo esc_html( implode( ' · ', array_filter( array( implode( ', ', $event['platforms'] ), $event['region'] ) ) ) ); ?></p><?php } ?>
<?php if ( $event['services'] ) { ?><div class="release-card-services"><?php foreach ( $event['services'] as $service ) { ?><a href="<?php echo esc_url( $service['url'] ); ?>"><?php echo self::service_logo( $service ); ?><span><?php echo esc_html( $service['title'] ); ?></span></a><?php } ?></div><?php } ?>
</div></article><?php Attribution::collect( $r, array( 'title', $event['field'] ) ); Attribution::collect_image( $r ); } ?>
</div></section>
<?php } ?>
<?php if ( ! $d['total'] ) { ?><div class="release-guide-empty"><h3>No matching releases</h3><p>Try another month or clear the service and title filters.</p><a data-release-nav href="<?php echo esc_url( self::url( array_replace( $f, array( 'type' => '', 'service' => '', 'search' => '', 'page' => 1 ) ), $base ) ); ?>">Clear filters</a></div><?php } ?>
</div>
<?php if ( $d['pages'] > 1 ) { ?><nav class="release-guide-pagination" aria-label="Release result pages"><?php for ( $p = max( 1, $f['page'] - 2 ); $p <= min( $d['pages'], $f['page'] + 2 ); ++$p ) { ?><a data-release-nav href="<?php echo esc_url( self::url( array_replace( $f, array( 'page' => $p ) ), $base ) ); ?>"<?php echo $p === $f['page'] ? ' aria-current="page"' : ''; ?>><?php echo $p; ?></a><?php } ?></nav><?php } ?>
<p class="release-guide-note">Dates reflect the published catalog and may change. A service assignment is not a guarantee of availability in every country. Releases without an exact date remain on their title pages.</p>
</div>
